/* ---------- v54: new technical films (part 1) — extra drawing helpers ---------- */
/* big berry cross-section: skin, pulp, seeds; ferm = intracellular bubbles */
const xBerry=(x,y,r,o)=>{ o=o||{}; const sk=o.skin||"#4a1236", pu=o.pulp||"#d9c98a"; let g=`<g transform="translate(${x} ${y})"><circle r="${r}" fill="${sk}"/><circle r="${r*.86}" fill="${pu}"/>`;
  if(o.colour) g+=`<circle r="${r*.86}" fill="#8a1f3e" opacity="0"><animate attributeName="opacity" from="0" to=".75" begin="${o.colour}s" dur="4s" fill="freeze"/></circle>`;
  g+=[[-.3,-.2],[.25,-.25],[0,.3]].map(([a,b])=>`<ellipse cx="${a*r}" cy="${b*r}" rx="${r*.12}" ry="${r*.18}" fill="#c9a46a" stroke="#8a6a3a" stroke-width=".6"/>`).join("");
  if(o.ferm) g+=Array.from({length:9},(_,i)=>`<circle cx="${Math.cos(i*2.1)*r*.5}" cy="${r*.5}" r="${r*.05+(i%3)*.4}" fill="rgba(255,255,255,.85)"><animate attributeName="cy" from="${r*.55}" to="${-r*.6}" dur="${1.6+(i%4)*.4}s" begin="${-i*.3}s" repeatCount="indefinite"/></circle>`).join("");
  g+=`<path d="M${-r*.5} ${-r*.75}A${r} ${r} 0 0 1 ${r*.4} ${-r*.85}" stroke="rgba(255,255,255,.35)" stroke-width="${r*.08}" fill="none" stroke-linecap="round"/></g>`; return g; };
/* whole bunch, bigger and rounder than fBunch */
const xBunch=(x,y,s,col)=>{ let g=`<g transform="translate(${x} ${y}) scale(${s||1})"><path d="M0 -14V0M0 -10l8 -6" stroke="#6b4a32" stroke-width="2" fill="none"/>`;
  [[5,0],[5,6],[4,12],[4,18],[3,24],[2,30],[1,35]].forEach(([n,yy])=>{ for(let i=0;i<n;i++){ const cx=(i-(n-1)/2)*6; g+=`<circle cx="${cx}" cy="${yy+3}" r="3.6" fill="${col||"#4a1236"}"/><circle cx="${cx-1.2}" cy="${yy+1.8}" r="1" fill="rgba(255,255,255,.35)"/>`; } }); return g+"</g>"; };
/* CO2 blanket */
const xCO2=(x,y,w,n)=>Array.from({length:n||7},(_,i)=>`<text x="${x+10+i*(w-20)/Math.max(1,(n||7)-1)}" y="${y}" font-size="7" fill="#bfe3f5" text-anchor="middle" font-weight="800" opacity=".85">CO₂<animate attributeName="y" values="${y};${y-5};${y}" dur="${2+(i%3)*.5}s" repeatCount="indefinite"/></text>`).join("");
/* glass of rosé / wine, tinted */
const xRoseRow=(cols,labs,y)=>cols.map((c,i)=>{ const x=40+i*(240/(cols.length-1)); return fD(.2+i*.25,fGlass(x,y||120,c,1.15)+(labs?fT(x,(y||120)+46,tx(labs[i]),8,"#fff4dc","middle",700,14):"")); }).join("");
/* molecule card */
const xMol=(x,y,lab,col,sub)=>`<g transform="translate(${x} ${y})"><circle r="22" fill="${col}" opacity=".9"/><circle r="22" fill="none" stroke="rgba(255,255,255,.5)"/>${fT(0,-1,lab,8.5,"#fff","middle",800)}${sub?fT(0,10,sub,6.5,"#fff4dc","middle",600):""}</g>`;
/* lactic bacteria */
const xBact=(x,y,d)=>`<g transform="translate(${x} ${y})"><g><animateTransform attributeName="transform" type="translate" values="0 0;${d||8} -4;0 0" dur="${2.4+(x%3)*.3}s" repeatCount="indefinite"/><rect x="-7" y="-2.6" width="14" height="5.2" rx="2.6" fill="#9fd36a" stroke="#4f7a28" stroke-width=".7"/><rect x="5" y="-2.6" width="12" height="5.2" rx="2.6" fill="#9fd36a" stroke="#4f7a28" stroke-width=".7"/></g></g>`;
/* botrytised berry (shrivelled, grey bloom) */
const xBotry=(x,y,r)=>`<g transform="translate(${x} ${y})"><path d="M${-r} 0Q${-r} ${-r} 0 ${-r}Q${r*.8} ${-r*1.05} ${r} ${-r*.1}Q${r*1.05} ${r*.9} 0 ${r}Q${-r*.9} ${r*1.05} ${-r} 0Z" fill="#7a4a2a"/><path d="M${-r*.6} ${-r*.2}q${r*.3} ${r*.3} ${r*.6} 0M${-r*.2} ${r*.4}q${r*.3} ${-r*.2} ${r*.6} ${r*.1}" stroke="#4e2d18" stroke-width="${r*.12}" fill="none"/>${Array.from({length:10},(_,i)=>`<circle cx="${Math.cos(i)*r*.7}" cy="${Math.sin(i*1.7)*r*.7}" r="${r*.09}" fill="#cfc6b8" opacity=".9"/>`).join("")}</g>`;
/* drying rack (appassimento / soleo) */
const xRack=(x,y,w,dry)=>`<g transform="translate(${x} ${y})">${[0,1,2].map(r=>`<rect x="0" y="${r*26}" width="${w}" height="4" fill="#8a5a33"/>${Array.from({length:Math.floor(w/22)},(_,i)=>xBunch(12+i*22,r*26-30,.5,dry?mixC("#4a1236","#3a1e12",.6):"#4a1236")).join("")}`).join("")}<path d="M2 -6V78M${w-2} -6V78" stroke="#6b4426" stroke-width="3"/></g>`;
/* sun-drying mats (PX soleo / passerillage) */
const xMats=(x,y,n)=>`<g transform="translate(${x} ${y})">${Array.from({length:n||4},(_,i)=>`<rect x="${i*62}" y="0" width="54" height="10" rx="2" fill="#c9a96a"/>${[0,1,2].map(k=>xBunch(i*62+12+k*15,-14,.42,"#5b2a2a")).join("")}`).join("")}</g>`;
/* puttony (hod) */
const xHod=(x,y,s)=>`<g transform="translate(${x} ${y}) scale(${s||1})"><path d="M-12 -30H12L9 0H-9Z" fill="#9a7a4a" stroke="#5a4426"/>${[0,1,2,3].map(i=>`<path d="M-11 ${-24+i*6}H11" stroke="#6b5232" stroke-width="1"/>`).join("")}${[0,1,2,3,4].map(i=>`<circle cx="${-8+i*4}" cy="-32" r="2.6" fill="#7a4a2a"/>`).join("")}</g>`;
/* Prädikat ladder: bars of rising height */
const xLadder=(labs,cur,o)=>{ o=o||{}; const n=labs.length, bw=(280-(n-1)*6)/n; return labs.map((l,i)=>{ const h=34+i*(110/(n-1)), x=20+i*(bw+6), on=i===cur;
  return fD(.15+i*.22,`<rect x="${x}" y="${178-h}" width="${bw}" height="${h}" rx="4" fill="${on?"#d4a23a":mixC("#f1e3a6","#b06a2a",i/(n-1))}" opacity="${on?1:.85}"/>${fT(x+bw/2,172-h,"▲",7,on?"#d4a23a":"rgba(255,244,220,.5)")}${fT(x+bw/2,190,l,7,"#fff4dc","middle",700)}${o.sub?fT(x+bw/2,178-h+14,o.sub[i],6.5,"#2a1b20","middle",800):""}`); }).join(""); };
/* sherry butt 5/6 full with flor */
const xButt=(x,y,s,o)=>fBarrel(x,y,s,Object.assign({cut:1,col:"#efe1a0"},o||{}));
/* venencia */
const xVenencia=(x,y)=>`<g transform="translate(${x} ${y})"><path d="M0 -70V0" stroke="#c9ced3" stroke-width="2"/><path d="M-4 -78Q0 -86 4 -78" stroke="#c9ced3" stroke-width="2" fill="none"/><rect x="-4" y="0" width="8" height="18" rx="2" fill="#c9ced3"/></g>`;
/* still: aguardente */
const xStill=(x,y)=>`<g transform="translate(${x} ${y})"><path d="M-22 0V-36Q-22 -50 0 -50Q22 -50 22 -36V0Z" fill="#b8733a" stroke="#7a4a20"/><path d="M0 -50V-62H34V-20" stroke="#b8733a" stroke-width="4" fill="none"/><rect x="28" y="-24" width="12" height="20" rx="2" fill="#c9ced3"/>${fDrops(34,-4,10,"#f3e8c8",3)}</g>`;
/* bottle row with label colours */
const xPortBottles=(cols,labs)=>cols.map((c,i)=>{ const x=36+i*(248/(cols.length-1)); return fD(.2+i*.2,fBottle(x,120,{col:c,label:1,cork:1})+fT(x,176,tx(labs[i]),7.6,"#fff4dc","middle",700,12)); }).join("");
const xBox=(x,y,w,h,t,c)=>fBox(x,y,w,h,t,{fill:c||"rgba(255,248,232,.1)"});
const xBoxD=(x,y,w,h,t)=>fBox(x,y,w,h,t,{fill:"rgba(42,27,32,.82)",stroke:"rgba(212,162,58,.8)"});

FILMS.push(
/* ===================== CARBONIC & SEMI-CARBONIC ===================== */
{id:"carb",sec:"c",ch:"red",ic:"order",nw:1,t:I3("Macerazione carbonica e semicarbonica","Macération carbonique et semi-carbonique","Carbonic and semi-carbonic maceration"),s:[
 {h:I3("Perché fermentare grappoli interi","Pourquoi fermenter des grappes entières","Why ferment whole bunches"),
  c:I3("Alcuni rossi devono essere fruttati, morbidi e pronti da bere subito. Per ottenerli, invece di pigiare l'uva, si mettono in vasca grappoli interi e intatti. Gli acini interi fermentano dall'interno e danno colore, poco tannino e aromi molto particolari. È la tecnica simbolo del Beaujolais.",
   "Certains rouges doivent être fruités, souples et prêts à boire tout de suite. Pour les obtenir, au lieu de fouler le raisin, on met en cuve des grappes entières et intactes. Les baies entières fermentent de l'intérieur et donnent de la couleur, peu de tanin et des arômes très particuliers. C'est la technique emblématique du Beaujolais.",
   "Some reds are meant to be fruity, soft and ready to drink straight away. To make them, instead of crushing the grapes, whole, intact bunches go into the vat. The whole berries ferment from the inside, giving colour, little tannin and very distinctive aromas. It is the signature technique of Beaujolais."),
  v:()=>fSvg(`${fD(.1,xBunch(70,70,1.6))}${fD(.4,xBunch(118,64,1.5,"#5a1640"))}${fD(.7,xBunch(94,96,1.4))}${fD(1.2,fArrow("M150 110H200",null,1))}${fTank(210,50,80,110,{col:"#3d0f22",lv:.9})}${fD(1.5,xBunch(232,70,.8)+xBunch(262,74,.8)+xBunch(248,100,.8)+xBunch(228,126,.7)+xBunch(268,128,.7))}${fChip(250,40,w3("grappoli interi","grappes entières","whole bunches"))}${fChip(100,180,"Beaujolais · Gamay")}`)},
 {h:I3("Il Gamay e la patria della tecnica","Le gamay et la patrie de la technique","Gamay and the home of the technique"),
  c:I3("Il vitigno simbolo è il Gamay, a buccia sottile, con acidità vivace e tannino naturalmente basso. In Beaujolais la macerazione carbonica e la semicarbonica danno vini da bere giovani, come il Beaujolais Nouveau, messo in vendita il terzo giovedì di novembre, poche settimane dopo la vendemmia. La tecnica si usa anche per Grenache, Carignan e Tempranillo.",
   "Le cépage emblématique est le gamay, à peau fine, avec une acidité vive et des tanins naturellement bas. Dans le Beaujolais, la macération carbonique et la semi-carbonique donnent des vins à boire jeunes, comme le beaujolais nouveau, mis en vente le troisième jeudi de novembre, quelques semaines après les vendanges. La technique sert aussi pour le grenache, le carignan et le tempranillo.",
   "The signature grape is Gamay, thin-skinned, with lively acidity and naturally low tannin. In Beaujolais, carbonic and semi-carbonic maceration give wines to drink young, such as Beaujolais Nouveau, released on the third Thursday of November, just weeks after harvest. The technique is also used for Grenache, Carignan and Tempranillo."),
  v:()=>fSvg(`${fD(.1,xBunch(70,92,1.7,"#3d1240"))}${fD(.5,fCall(92,70,170,40,w3("buccia sottile","peau fine","thin skin")))}${fD(1,fCall(92,96,190,74,w3("acidità vivace","acidité vive","lively acidity")))}${fD(1.5,fCall(92,120,200,108,w3("tannino basso","tanin bas","low tannin")))}${fD(2.2,xBoxD(196,128,112,30,w3("Nouveau: 3° giovedì di novembre","Nouveau : 3e jeudi de novembre","Nouveau: 3rd Thursday of November")))}${fChip(60,182,"Gamay · Beaujolais")}${fD(2.8,fChip(232,182,"Grenache · Carignan · Tempranillo","#6e1630"))}`)},
 {h:I3("La macerazione carbonica: una vasca piena di CO₂","La macération carbonique : une cuve pleine de CO₂","Carbonic maceration: a vat full of CO₂"),
  c:I3("Nella macerazione carbonica vera e propria la vasca viene prima riempita di anidride carbonica, poi caricata con grappoli interi e chiusa. Senza ossigeno, e senza lieviti al lavoro, gli acini restano integri: è l'ambiente perfetto per una fermentazione diversa, che avviene dentro ogni singolo acino.",
   "Dans la vraie macération carbonique, la cuve est d'abord remplie de gaz carbonique, puis chargée de grappes entières et fermée. Sans oxygène, et sans levures au travail, les baies restent intactes : c'est le milieu idéal pour une fermentation différente, qui se déroule à l'intérieur de chaque baie.",
   "In full carbonic maceration the vat is first filled with carbon dioxide, then loaded with whole bunches and sealed. With no oxygen, and no yeast at work, the berries stay intact: the perfect setting for a different kind of fermentation, which happens inside each individual berry."),
  v:()=>fSvg(`${fTank(110,40,100,130,{col:"rgba(160,210,240,.25)",lv:.95})}${xCO2(118,64,84,6)}${xCO2(118,84,84,5)}${fD(.6,xBunch(140,96,.9)+xBunch(176,100,.9)+xBunch(158,128,.9)+xBunch(132,140,.8)+xBunch(186,140,.8))}${fD(.2,`<path d="M40 70H100" stroke="#9fd3f0" stroke-width="5" marker-end="url(#fah)"/>`+fChip(64,60,"CO₂"))}${fD(1,fCall(210,60,262,48,w3("vasca chiusa, senza ossigeno","cuve fermée, sans oxygène","sealed vat, no oxygen")))}${fD(1.6,fCall(186,132,264,150,w3("acini intatti","baies intactes","intact berries")))}`)},
 {h:I3("Uve intatte: la vendemmia a mano","Des raisins intacts : la vendange manuelle","Intact grapes: hand harvesting"),
  c:I3("Perché la tecnica funzioni, i grappoli devono arrivare in cantina interi e con gli acini integri. Per questo si vendemmia a mano e si trasporta l'uva in piccole cassette, senza schiacciarla. Gli acini rotti fermenterebbero subito con i lieviti, come in una vinificazione classica.",
   "Pour que la technique fonctionne, les grappes doivent arriver au chai entières, avec des baies intactes. On vendange donc à la main et on transporte le raisin dans de petites caisses, sans l'écraser. Les baies abîmées fermenteraient aussitôt avec les levures, comme dans une vinification classique.",
   "For the technique to work, the bunches must reach the winery whole, with intact berries. So they are picked by hand and carried in small crates, without crushing them. Broken berries would start fermenting straight away with yeast, as in a classic ferment."),
  v:()=>fSvg(`${fD(.1,xHod(70,130,1.6))}${fD(.4,xBunch(70,70,.9)+xBunch(88,78,.8))}${fD(1,fArrow("M110 120H160",null,1))}${fD(1.2,`<rect x="170" y="104" width="70" height="34" rx="4" fill="#9a7a4a" stroke="#5a4426"/>`+xBunch(190,104,.7)+xBunch(218,104,.7))}${fChip(205,92,w3("cassette piccole","petites caisses","small crates"))}${fD(1.8,xBoxD(170,152,140,26,w3("acini integri: niente pigiatura","baies intactes : pas de foulage","intact berries: no crushing")))}${fChip(70,180,w3("vendemmia manuale","vendange manuelle","hand harvest"))}`)},
 {h:I3("La fermentazione intracellulare","La fermentation intracellulaire","Intracellular fermentation"),
  c:I3("Dentro l'acino intatto, gli enzimi della polpa trasformano una parte dello zucchero in alcol, fino a circa il 2 per cento, senza l'intervento dei lieviti. Intanto il colore passa dalla buccia alla polpa, ma il tannino viene estratto pochissimo. Si formano anche aromi tipici: kirsch, banana, cannella, a volte gomma da masticare.",
   "Dans la baie intacte, les enzymes de la pulpe transforment une partie du sucre en alcool, jusqu'à environ 2 pour cent, sans l'intervention des levures. Pendant ce temps, la couleur passe de la peau à la pulpe, mais le tanin est très peu extrait. Il se forme aussi des arômes typiques : kirsch, banane, cannelle, parfois chewing-gum.",
   "Inside the intact berry, enzymes in the pulp turn part of the sugar into alcohol, up to about 2 percent, with no help from yeast. Meanwhile colour moves from the skin into the pulp, but very little tannin is extracted. Distinctive aromas also form: kirsch, banana, cinnamon, sometimes bubblegum."),
  v:()=>fSvg(`${xBerry(110,100,62,{ferm:1,colour:.6})}${fD(.3,fCall(110,60,200,36,w3("enzimi: zucchero → alcol (≈2 %)","enzymes : sucre → alcool (≈2 %)","enzymes: sugar → alcohol (≈2%)")))}${fD(1.4,fCall(150,120,230,88,w3("colore nella polpa","couleur dans la pulpe","colour into the pulp")))}${fD(2.4,fCall(80,150,230,140,w3("pochissimo tannino","très peu de tanin","very little tannin")))}${fD(3.2,fChip(250,176,w3("kirsch · banana · cannella","kirsch · banane · cannelle","kirsch · banana · cinnamon"),"#8c1d40"))}`)},
 {h:I3("Calore e 2 % di alcol: la buccia si rompe","Chaleur et 2 % d'alcool : la peau éclate","Warmth and 2% alcohol: the skins split"),
  c:I3("La fermentazione intracellulare lavora meglio al caldo, intorno ai trenta gradi, e dura alcuni giorni. Gli enzimi consumano anche una parte dell'acido malico, per questo il vino risulta morbido. Quando l'alcol dentro l'acino arriva a circa il 2 per cento, le bucce si rompono, il succo esce e i lieviti prendono il comando.",
   "La fermentation intracellulaire travaille mieux au chaud, autour de trente degrés, et dure quelques jours. Les enzymes consomment aussi une partie de l'acide malique : le vin en ressort plus souple. Quand l'alcool dans la baie atteint environ 2 pour cent, les peaux éclatent, le jus s'écoule et les levures prennent le relais.",
   "Intracellular fermentation works best when warm, around thirty degrees Celsius, and lasts a few days. The enzymes also use up part of the malic acid, which is why the wine feels soft. When the alcohol inside the berry reaches about 2 percent, the skins split, the juice runs out and yeast takes over."),
  v:()=>fSvg(`${fD(.1,fThermo(40,60,"≈ 30 °C",.8,"#c0263f"))}${fD(.6,xBerry(140,96,46,{ferm:1,colour:.7}))}<path d="M140 50l-6 14l8 6l-6 14" stroke="#fff4dc" stroke-width="2.4" fill="none" opacity="0">${'<animate attributeName="opacity" from="0" to="1" begin="2s" dur=".4s" fill="freeze"/>'}</path>${fD(1.2,fCall(176,80,248,44,w3("alcol ≈ 2 %","alcool ≈ 2 %","alcohol ≈ 2%")))}${fD(2,fCall(176,104,256,96,w3("buccia che si rompe","peau qui éclate","skin splits")))}${fD(2.8,fCall(170,128,252,146,w3("meno acido malico","moins d'acide malique","less malic acid")))}${fD(3.4,fYeast(110,160)+fYeast(130,170))}`)},
 {h:I3("Pressatura e fine della fermentazione","Pressurage et fin de la fermentation","Pressing and finishing fermentation"),
  c:I3("Dopo alcuni giorni, di solito da cinque a quindici, gli acini vengono pressati. Il mosto, già colorato, finisce la fermentazione con i lieviti, lontano dalle bucce, quasi come un vino bianco. Così il vino resta di colore vivo, con tannino basso e frutto rosso esuberante.",
   "Après quelques jours, en général de cinq à quinze, les baies sont pressurées. Le moût, déjà coloré, termine sa fermentation avec les levures, loin des peaux, presque comme un vin blanc. Le vin garde ainsi une couleur vive, un tanin bas et un fruit rouge exubérant.",
   "After a few days, usually five to fifteen, the berries are pressed. The already coloured juice finishes fermenting with yeast, away from the skins, almost like a white wine. The wine keeps a vivid colour, low tannin and exuberant red fruit."),
  v:()=>fSvg(`${fPress(30,60,"#8a1f3e","#4a1236")}${fD(1,fArrow("M150 130H190",null,1))}${fTank(200,60,80,100,{col:"#7a1530",lv:.7,bub:10})}${fD(1.4,fYeast(226,120)+fYeast(254,136))}${fChip(85,40,w3("5–15 giorni, poi pressatura","5–15 jours, puis pressurage","5–15 days, then pressing"))}${fD(1.8,fChip(240,44,w3("finisce senza bucce","finit sans les peaux","finishes off the skins")))}`)},
 {h:I3("Vino fiore e vino di pressa","Vin de goutte et vin de presse","Free-run and press wine"),
  c:I3("Alla svinatura si separa il vino fiore, che scorre da solo, dalla massa di acini ancora pieni di succo zuccherino. Questi vanno in pressa: qui il vino di pressa è spesso il più ricco e aromatico, al contrario di quanto accade di solito. Le due parti si assemblano, fanno la malolattica e il vino viene imbottigliato presto.",
   "Au décuvage, on sépare le vin de goutte, qui s'écoule tout seul, de la masse de baies encore pleines de jus sucré. Celles-ci passent au pressoir : ici, le vin de presse est souvent le plus riche et le plus aromatique, à l'inverse de ce qui se passe d'habitude. Les deux parts sont assemblées, font leur malolactique, et le vin est mis en bouteille tôt.",
   "At draining, the free-run wine, which flows out by itself, is separated from the mass of berries still full of sweet juice. These go to the press: here the press wine is often the richest and most aromatic, the opposite of what usually happens. The two parts are blended, go through malolactic conversion, and the wine is bottled early."),
  v:()=>fSvg(`${fTank(24,50,70,110,{col:"#7a1530",lv:.6})}${fD(.4,fArrow("M96 140H128",null,1))}${fD(.6,fGlass(146,140,"#9b2045",1))}${fChip(146,180,w3("vino fiore","vin de goutte","free run"))}${fD(1.2,fPress(176,56,"#8a1f3e","#4a1236"))}${fD(1.8,fGlass(290,140,"#6e1630",1.1))}${fChip(282,180,w3("vino di pressa","vin de presse","press wine"))}${fD(2.4,xBoxD(176,24,138,24,w3("qui la pressa è più ricca","ici la presse est plus riche","here press wine is richer")))}`)},
 {h:I3("La semicarbonica: il metodo più diffuso","La semi-carbonique : la méthode la plus répandue","Semi-carbonic: the most common method"),
  c:I3("Nella semicarbonica non si aggiunge anidride carbonica. I grappoli interi vengono caricati in vasca e il loro peso schiaccia gli acini sul fondo. Quel mosto fermenta subito con i lieviti e produce anidride carbonica, che sale e protegge gli acini interi in alto. Così, sopra, avviene la fermentazione intracellulare. È il metodo più usato in Beaujolais.",
   "Dans la semi-carbonique, on n'ajoute pas de gaz carbonique. Les grappes entières sont chargées en cuve et leur poids écrase les baies du fond. Ce moût fermente aussitôt avec les levures et produit du gaz carbonique, qui monte et protège les baies entières du haut. Là, au-dessus, a lieu la fermentation intracellulaire. C'est la méthode la plus utilisée en Beaujolais.",
   "In semi-carbonic maceration no carbon dioxide is added. Whole bunches are loaded into the vat and their weight crushes the berries at the bottom. That juice starts fermenting with yeast and gives off carbon dioxide, which rises and protects the whole berries above. Up there, intracellular fermentation takes place. It is the most widely used method in Beaujolais."),
  v:()=>fSvg(`${fTank(100,30,120,150,{col:"rgba(120,20,50,.2)",lv:.98})}<rect x="105" y="140" width="110" height="36" fill="#7a1530"/>${Array.from({length:8},(_,i)=>`<circle cx="${112+i*14}" cy="174" r="1.6" fill="#fff"><animate attributeName="cy" from="174" to="140" dur="${1.4+(i%3)*.3}s" begin="${-i*.3}s" repeatCount="indefinite"/></circle>`).join("")}${xCO2(110,58,100,5)}${fD(.3,xBunch(128,70,.85)+xBunch(160,74,.85)+xBunch(192,70,.85)+xBunch(144,104,.85)+xBunch(178,104,.85))}${fD(.8,fCall(210,156,262,170,w3("mosto: lieviti al lavoro","moût : levures au travail","juice: yeast at work")))}${fD(1.6,fCall(210,60,262,40,w3("CO₂ prodotta dai lieviti","CO₂ produit par les levures","CO₂ made by the yeast")))}${fD(2.4,fCall(190,100,262,104,w3("acini interi: intracellulare","baies entières : intracellulaire","whole berries: intracellular")))}`)},
 {h:I3("Grappolo intero in una fermentazione classica","Grappes entières dans une fermentation classique","Whole bunches in a classic ferment"),
  c:I3("Molti produttori aggiungono solo una parte di grappoli interi a una fermentazione tradizionale di uva pigiata, come in Borgogna o nel Rodano. Il vino guadagna frutto rosso fresco, un profumo più vivace e, se si usano anche i raspi maturi, note erbacee e speziate e un po' di tannino in più.",
   "Beaucoup de producteurs ajoutent seulement une part de grappes entières à une fermentation traditionnelle de raisin foulé, comme en Bourgogne ou dans le Rhône. Le vin y gagne un fruit rouge frais, un parfum plus vif et, si l'on garde des rafles mûres, des notes herbacées et épicées et un peu plus de tanin.",
   "Many producers add just a share of whole bunches to a traditional ferment of crushed grapes, as in Burgundy or the Rhône. The wine gains fresh red fruit, a livelier perfume and, if ripe stems are kept, herbal, spicy notes and a little extra tannin."),
  v:()=>fSvg(`${fTank(60,50,110,120,{col:"#5a0f24",lv:.8,cap:1})}${fD(.4,xBunch(90,86,.7)+xBunch(130,90,.7))}${fChip(115,38,w3("pigiato + 20–50 % grappoli interi","foulé + 20–50 % grappes entières","crushed + 20–50% whole bunches"))}${fD(1,xBox(196,58,104,26,w3("frutto rosso fresco","fruit rouge frais","fresh red fruit")))}${fD(1.6,xBox(196,92,104,26,w3("profumo più vivace","parfum plus vif","livelier perfume")))}${fD(2.2,xBox(196,126,104,26,w3("raspi: erbe, spezie, tannino","rafles : herbes, épices, tanin","stems: herbs, spice, tannin")))}${fChip(160,186,w3("Borgogna · Rodano","Bourgogne · Rhône","Burgundy · Rhône"))}`)},
 {h:I3("Dove si usa nel mondo","Où l'utilise-t-on dans le monde","Where it is used around the world"),
  c:I3("In Beaujolais per il Gamay. Nel Sud della Francia per ammorbidire i tannini rustici del Carignan e per i Grenache economici del Rodano. In Rioja per i vini giovani, joven o cosechero, di Tempranillo, freschi e profumati di fragola. E molti Pinot Noir di alta qualità usano una parte di grappoli interi o una fase semicarbonica, ma finiscono di fermentare sulle bucce.",
   "Dans le Beaujolais pour le gamay. Dans le Sud de la France pour assouplir les tanins rustiques du carignan et pour les grenaches bon marché du Rhône. En Rioja pour les vins jeunes, joven ou cosechero, de tempranillo, frais et parfumés à la fraise. Et beaucoup de pinots noirs haut de gamme utilisent une part de grappes entières ou une phase semi-carbonique, mais finissent leur fermentation sur les peaux.",
   "In Beaujolais for Gamay. In the South of France to soften the rustic tannins of Carignan and for inexpensive Rhône Grenache. In Rioja for young wines, joven or cosechero, made from Tempranillo, fresh and strawberry-scented. And many premium Pinot Noirs use a share of whole bunches or a semi-carbonic phase, but finish fermenting on the skins."),
  v:()=>fSvg(`${fD(.1,xBoxD(14,30,142,34,w3("Beaujolais · Gamay","Beaujolais · Gamay","Beaujolais · Gamay")))}${fD(.6,xBoxD(164,30,142,34,w3("Sud Francia · Carignan","Sud de la France · Carignan","Southern France · Carignan")))}${fD(1.1,xBoxD(14,76,142,34,w3("Rodano · Grenache","Rhône · Grenache","Rhône · Grenache")))}${fD(1.6,xBoxD(164,76,142,34,w3("Rioja joven · Tempranillo","Rioja joven · Tempranillo","Rioja joven · Tempranillo")))}${fD(2.1,xBox(54,122,212,34,w3("Pinot Noir: grappoli interi, poi sulle bucce","Pinot noir : grappes entières, puis sur peaux","Pinot Noir: whole bunches, then on skins"),"rgba(163,38,79,.4)"))}${fD(2.6,fChip(160,178,w3("ammorbidire i tannini del Carignan","assouplir les tanins du carignan","soften Carignan's tannins"),"#6e1630"))}`)},
 {h:I3("Riconoscerli nel bicchiere","Les reconnaître dans le verre","Spotting them in the glass"),
  c:I3("Un rosso da macerazione carbonica ha colore porpora vivo, tannino basso, acidità fresca e profumi esplosivi di ciliegia, lampone, kirsch, a volte banana e cannella. Si beve giovane e leggermente fresco. Gli esempi tipici: Beaujolais e Beaujolais Nouveau, alcuni Côtes du Rhône e Languedoc, i giovani Rioja da cosechero.",
   "Un rouge de macération carbonique a une couleur pourpre vive, un tanin bas, une acidité fraîche et des arômes explosifs de cerise, framboise, kirsch, parfois banane et cannelle. Il se boit jeune et légèrement frais. Exemples typiques : beaujolais et beaujolais nouveau, certains côtes-du-rhône et languedoc, les jeunes rioja de cosechero.",
   "A carbonic-maceration red has a vivid purple colour, low tannin, fresh acidity and explosive aromas of cherry, raspberry, kirsch, sometimes banana and cinnamon. It is drunk young and lightly chilled. Typical examples: Beaujolais and Beaujolais Nouveau, some Côtes du Rhône and Languedoc, young cosechero Rioja."),
  v:()=>fSvg(`${fD(.1,fGlass(80,120,"#7a1a5a",1.6))}${fD(.6,fCall(92,96,170,40,w3("porpora vivo","pourpre vif","vivid purple")))}${fD(1.1,fCall(92,120,190,76,w3("tannino basso","tanin bas","low tannin")))}${fD(1.6,fCall(92,140,200,112,w3("ciliegia · kirsch · banana","cerise · kirsch · banane","cherry · kirsch · banana")))}${fD(2.1,fCall(92,160,190,148,w3("da bere giovane e fresco","à boire jeune et frais","drink young, lightly chilled")))}${fD(2.6,fChip(240,186,"Beaujolais · Rioja joven · Languedoc"))}`)},
 {h:I3("Vantaggi e limiti","Avantages et limites","Advantages and limits"),
  c:I3("I vantaggi: vini pronti in poche settimane, colore intenso senza durezza, frutto esplosivo e tannino morbido, ideali per uve rustiche o tanniche. I limiti: gli aromi di fermentazione, banana e gomma da masticare, possono coprire il carattere del vitigno e del terroir, e questi vini in genere non sono fatti per invecchiare.",
   "Les avantages : des vins prêts en quelques semaines, une couleur intense sans dureté, un fruit explosif et des tanins souples, idéal pour des cépages rustiques ou tanniques. Les limites : les arômes de fermentation, banane et chewing-gum, peuvent masquer le caractère du cépage et du terroir, et ces vins ne sont en général pas faits pour vieillir.",
   "The advantages: wines ready within weeks, intense colour without harshness, explosive fruit and soft tannin, ideal for rustic or tannic grapes. The limits: fermentation aromas, banana and bubblegum, can mask the character of the grape and the terroir, and these wines are generally not made for ageing."),
  v:()=>fSvg(`${fT(84,40,w3("Vantaggi","Avantages","Advantages"),12,"#9fe0a8")}${fD(.3,xBox(14,52,140,24,w3("pronto in poche settimane","prêt en quelques semaines","ready within weeks"),"rgba(60,140,80,.35)"))}${fD(.7,xBox(14,82,140,24,w3("colore senza durezza","couleur sans dureté","colour, no harshness"),"rgba(60,140,80,.35)"))}${fD(1.1,xBox(14,112,140,24,w3("frutto esplosivo","fruit explosif","explosive fruit"),"rgba(60,140,80,.35)"))}${fD(1.5,xBox(14,142,140,24,w3("ammorbidisce uve rustiche","assouplit les cépages rustiques","softens rustic grapes"),"rgba(60,140,80,.35)"))}${fT(236,40,w3("Limiti","Limites","Limits"),12,"#ffb3a8")}${fD(2,xBox(166,52,140,34,w3("banana e chewing-gum coprono vitigno e terroir","banane et chewing-gum masquent cépage et terroir","banana and bubblegum mask grape and terroir"),"rgba(190,60,50,.35)"))}${fD(2.6,xBox(166,94,140,24,w3("poco adatto all'invecchiamento","peu fait pour vieillir","not made for ageing"),"rgba(190,60,50,.35)"))}`)},
 {h:I3("I cru del Beaujolais: un'altra storia","Les crus du Beaujolais : une autre histoire","The Beaujolais crus: a different story"),
  c:I3("Sulle colline granitiche del nord, i dieci cru, come Morgon, Moulin-à-Vent o Fleurie, usano macerazioni più lunghe, spesso semicarboniche o anche classiche, a volte con un passaggio in legno. Ne nascono vini più strutturati e concentrati, che possono invecchiare diversi anni. In pianura, invece, Beaujolais e Nouveau restano leggeri e fruttati.",
   "Sur les collines granitiques du nord, les dix crus, comme Morgon, Moulin-à-Vent ou Fleurie, pratiquent des macérations plus longues, souvent semi-carboniques ou même classiques, parfois avec un passage en bois. On obtient des vins plus structurés et concentrés, qui peuvent vieillir plusieurs années. En plaine, en revanche, le beaujolais et le nouveau restent légers et fruités.",
   "On the granite hills of the north, the ten crus, such as Morgon, Moulin-à-Vent or Fleurie, use longer macerations, often semi-carbonic or even classic, sometimes with time in oak. The result is more structured, concentrated wines that can age for several years. On the plain, by contrast, Beaujolais and Nouveau stay light and fruity."),
  v:()=>fSvg(`<path d="M0 150Q60 70 120 110T240 90T320 120V200H0Z" fill="#6b5a4a"/><path d="M0 170Q80 150 160 165T320 160V200H0Z" fill="#9aa86a"/>${fD(.3,fChip(112,96,w3("colline di granito: i 10 cru","collines granitiques : les 10 crus","granite hills: the 10 crus"),"#6e1630"))}${fD(.9,fChip(220,70,"Morgon · Moulin-à-Vent · Fleurie"))}${fD(1.5,fChip(90,186,w3("pianura: Beaujolais, Nouveau","plaine : beaujolais, nouveau","plain: Beaujolais, Nouveau")))}${fD(2.1,xBoxD(196,118,116,40,w3("più struttura, invecchia","plus de structure, vieillit","more structure, can age")))}`)},
 {h:I3("Ricapitolando","En résumé","Recap"),
  c:I3("Macerazione carbonica: grappoli interi e intatti in una vasca satura di anidride carbonica; fermentazione intracellulare dentro l'acino, al caldo, fino a circa il 2 per cento di alcol; poi pressatura e fine della fermentazione senza bucce. Semicarbonica: nessuna anidride carbonica aggiunta, il fondo pigiato fermenta e protegge gli acini sopra; è il metodo più usato in Beaujolais. Risultato: colore vivo, frutto esuberante, kirsch, banana e cannella, poco tannino, da bere giovane. Vitigni tipici: Gamay, Carignan, Grenache, Tempranillo.",
   "Macération carbonique : grappes entières et intactes dans une cuve saturée de gaz carbonique ; fermentation intracellulaire dans la baie, au chaud, jusqu'à environ 2 pour cent d'alcool ; puis pressurage et fin de fermentation sans les peaux. Semi-carbonique : pas de gaz ajouté, le fond écrasé fermente et protège les baies du dessus ; c'est la méthode la plus utilisée dans le Beaujolais. Résultat : couleur vive, fruit exubérant, kirsch, banane et cannelle, peu de tanin, à boire jeune. Cépages typiques : gamay, carignan, grenache, tempranillo.",
   "Carbonic maceration: whole, intact bunches in a vat saturated with carbon dioxide; intracellular fermentation inside the berry, kept warm, up to about 2 percent alcohol; then pressing and finishing off the skins. Semi-carbonic: no added carbon dioxide, the crushed bottom ferments and protects the berries above; it is the most widely used method in Beaujolais. Result: vivid colour, exuberant fruit, kirsch, banana and cinnamon, little tannin, to drink young. Typical grapes: Gamay, Carignan, Grenache, Tempranillo."),
  v:()=>fSvg(fTable(I3(["Tecnica","Effetto"],["Technique","Effet"],["Technique","Effect"])[L()].map(x=>I3(x,x,x)),[
    [I3("Carbonica: CO₂ aggiunta","Carbonique : CO₂ ajouté","Carbonic: CO₂ added"),I3("intracellulare pura","intracellulaire pure","pure intracellular")],
    [I3("Semicarbonica: nessuna CO₂","Semi-carbonique : sans CO₂","Semi-carbonic: no CO₂"),I3("fondo pigiato + intracellulare","fond écrasé + intracellulaire","crushed bottom + intracellular")],
    [I3("Grappolo intero parziale","Grappes entières partielles","Partial whole bunch"),I3("freschezza, profumo","fraîcheur, parfum","freshness, perfume")],
    [I3("Classica (pigiata)","Classique (foulée)","Classic (crushed)"),I3("più tannino ed estrazione","plus de tanin et d'extraction","more tannin and extraction")]],[0,1],{c1:150}))}
]},

/* ===================== ROSÉ ===================== */
{id:"rose",sec:"c",ch:"red",ic:"order",nw:1,t:I3("Come si fa un rosato: le quattro tecniche","Comment on fait un rosé : les quatre techniques","How rosé is made: the four techniques"),s:[
 {h:I3("Tutto il colore viene dalla buccia","Toute la couleur vient de la peau","All the colour comes from the skin"),
  c:I3("La polpa dell'uva nera è quasi sempre incolore: il colore sta nella buccia. Un rosato nasce quindi da uve nere lasciate a contatto con il mosto per poco tempo. Più lungo è il contatto, e più alta la temperatura, più il colore passa da buccia di cipolla e salmone pallido fino al rosa intenso e al lampone.",
   "La pulpe du raisin noir est presque toujours incolore : la couleur est dans la peau. Un rosé naît donc de raisins noirs laissés peu de temps au contact du moût. Plus le contact est long, et plus la température est élevée, plus la couleur passe de pelure d'oignon et saumon pâle au rose soutenu et à la framboise.",
   "The pulp of black grapes is almost always colourless: the colour is in the skin. A rosé is therefore made from black grapes left in contact with the juice for a short time. The longer the contact, and the higher the temperature, the more the colour moves from onion skin and pale salmon to deep pink and raspberry."),
  v:()=>fSvg(`${xBerry(70,80,40,{skin:"#3d0f2a",pulp:"#efe6c4"})}${fD(.4,fCall(100,62,170,34,w3("colore nella buccia","couleur dans la peau","colour in the skin")))}${xRoseRow(["#f6d7c0","#f3b7a6","#ec8f8d","#d9566e","#b02a4d"],null,150).replace(/translate\((\d+(\.\d+)?) 150\)/g,(m,a)=>`translate(${(+a)*.62+120} 150)`)}${fD(1.8,fChip(222,190,w3("contatto più lungo → più colore","contact plus long → plus de couleur","longer contact → more colour")))}`)},
 {h:I3("1. Pressatura diretta","1. Pressurage direct","1. Direct pressing"),
  c:I3("Le uve nere vengono pressate subito, come per un vino bianco. Durante la pressatura il mosto prende solo un velo di colore dalle bucce. Si ottengono rosati molto pallidi, delicati, spesso dal colore buccia di cipolla o salmone: è lo stile della Provenza, sempre più imitato nel mondo.",
   "Les raisins noirs sont pressurés tout de suite, comme pour un vin blanc. Pendant le pressurage, le moût ne prend qu'un voile de couleur aux peaux. On obtient des rosés très pâles, délicats, souvent couleur pelure d'oignon ou saumon : c'est le style de la Provence, de plus en plus imité dans le monde.",
   "The black grapes are pressed straight away, as for a white wine. During pressing the juice picks up only a hint of colour from the skins. The result is very pale, delicate rosés, often onion-skin or salmon in colour: the Provence style, more and more imitated around the world."),
  v:()=>fSvg(`${fD(.1,xBunch(46,70,1.1)+xBunch(76,76,1))}${fD(.4,fArrow("M96 100H120",null,1))}${fPress(124,70,"#f6cdb8","#4a1236")}${fD(1.4,fArrow("M240 150H262",null,1))}${fD(1.6,fGlass(286,140,"#f6d7c0",1.1))}${fChip(180,48,w3("subito in pressa","directement au pressoir","straight to the press"))}${fD(2,fChip(250,190,w3("pallido · Provenza","pâle · Provence","pale · Provence")))}`,"summer")},
 {h:I3("2. Macerazione breve","2. Macération courte","2. Short maceration"),
  c:I3("Le uve vengono pigiate e lasciate macerare con le bucce da poche ore fino a un paio di giorni. Quando il colore è quello voluto, il mosto viene separato e fermentato da solo, come un bianco. I rosati così ottenuti sono più colorati e strutturati: un esempio classico è il Tavel, nel Rodano meridionale.",
   "Les raisins sont foulés puis laissés macérer avec les peaux de quelques heures à deux jours environ. Quand la couleur voulue est atteinte, le moût est écoulé et fermenté seul, comme un blanc. Les rosés obtenus sont plus colorés et plus structurés : un exemple classique est le tavel, dans le sud de la vallée du Rhône.",
   "The grapes are crushed and left to macerate with the skins for a few hours up to a couple of days. When the colour is right, the juice is run off and fermented on its own, like a white. These rosés are deeper in colour and more structured: a classic example is Tavel, in the southern Rhône."),
  v:()=>fSvg(`${fTank(50,50,90,120,{col:"#b02a4d",lv:.7,cap:1})}${fD(.4,fClock(95,36,""))}${fChip(95,186,w3("poche ore → 2 giorni","quelques heures → 2 jours","a few hours → 2 days"))}${fD(1.2,`<path d="M140 150H180" stroke="#ec8f8d" stroke-width="4" marker-end="url(#fah)"/>`)}${fTank(186,70,80,100,{col:"#ec8f8d",lv:.6})}${fD(1.6,fChip(226,58,w3("fermenta senza bucce","fermente sans les peaux","ferments off the skins")))}${fD(2.2,fChip(226,186,"Tavel"))}`)},
 {h:I3("3. Salasso (saignée)","3. Saignée","3. Saignée (bleeding)"),
  c:I3("Mentre si prepara un vino rosso, poco dopo la pigiatura si preleva dalla vasca una parte del mosto, già rosato. Quel mosto fermenta a parte e diventa un rosato. Il vino rosso che resta ha più bucce in proporzione al liquido, quindi risulta più concentrato in colore, aromi e tannino.",
   "Pendant l'élaboration d'un vin rouge, peu après le foulage, on soutire de la cuve une partie du moût, déjà rosé. Ce moût fermente à part et devient un rosé. Le rouge qui reste a plus de peaux par rapport au liquide : il est donc plus concentré en couleur, en arômes et en tanin.",
   "While a red wine is being made, shortly after crushing, part of the already pink juice is drawn off from the vat. That juice ferments separately and becomes a rosé. The red that remains has more skins in proportion to liquid, so it ends up more concentrated in colour, flavour and tannin."),
  v:()=>fSvg(`${fTank(50,40,110,130,{col:"#5a0f24",lv:.85,colTo:"#3d0a18",cd:5,cb:1.5})}${fD(.4,`<path d="M160 150H196V176" stroke="#ec8f8d" stroke-width="4" fill="none" stroke-dasharray="6 4"><animate attributeName="stroke-dashoffset" from="20" to="0" dur=".8s" repeatCount="indefinite"/></path>`)}${fTank(200,90,80,80,{col:"#ec8f8d",lv:.65})}${fChip(105,28,w3("rosso più concentrato","rouge plus concentré","more concentrated red"))}${fD(1.4,fChip(240,78,w3("rosato di salasso","rosé de saignée","saignée rosé")))}`)},
 {h:I3("4. Taglio di vino rosso e bianco","4. Assemblage de rouge et de blanc","4. Blending red and white"),
  c:I3("La tecnica più semplice è mescolare un po' di vino rosso con del vino bianco. Nell'Unione europea, però, per i rosati fermi a denominazione questa pratica in genere non è permessa. La grande eccezione è lo Champagne rosato, spesso ottenuto proprio aggiungendo vino rosso allo Champagne bianco. Fuori dall'Europa è più diffusa.",
   "La technique la plus simple consiste à mélanger un peu de vin rouge avec du vin blanc. Dans l'Union européenne, cependant, cette pratique n'est en général pas permise pour les rosés tranquilles d'appellation. La grande exception est le champagne rosé, souvent obtenu justement en ajoutant du vin rouge au champagne blanc. Hors d'Europe, elle est plus répandue.",
   "The simplest technique is to mix a little red wine into white wine. In the European Union, however, this is generally not allowed for still rosés with a protected name. The big exception is rosé Champagne, often made precisely by adding red wine to white Champagne. Outside Europe it is more common."),
  v:()=>fSvg(`${fD(.1,fBottle(70,110,{col:"#e9dc8c",label:1}))}${fD(.3,fT(110,120,"+",22,"#d4a23a"))}${fD(.5,fBottle(150,110,{col:"#5a0f24",label:1}))}${fD(.8,fArrow("M180 110H214",null,1))}${fD(1.1,fFlute(254,118,"#f3a7a0",1.3))}${fChip(110,36,w3("UE: vietato per i rosati fermi","UE : interdit pour les rosés tranquilles","EU: not for still rosé"),"#8c1d40")}${fD(1.6,fChip(250,188,w3("ammesso: Champagne rosé","permis : champagne rosé","allowed: rosé Champagne")))}`)},
 {h:I3("La fermentazione: come un bianco","La fermentation : comme un blanc","Fermentation: like a white"),
  c:I3("Una volta separato dalle bucce, il mosto rosato viene vinificato come un bianco aromatico: fermentazione a bassa temperatura in acciaio, protezione dall'ossigeno, di solito niente malolattica e niente legno nuovo, per conservare frutto fresco e acidità. Alcuni rosati di alta gamma fermentano o affinano in legno per avere più struttura.",
   "Une fois séparé des peaux, le moût rosé est vinifié comme un blanc aromatique : fermentation à basse température en inox, protection contre l'oxygène, en général ni malolactique ni bois neuf, pour garder un fruit frais et l'acidité. Certains rosés haut de gamme fermentent ou s'élèvent en bois pour gagner en structure.",
   "Once off the skins, the pink juice is handled like an aromatic white: cool fermentation in stainless steel, protection from oxygen, usually no malolactic and no new oak, to keep fresh fruit and acidity. Some premium rosés are fermented or aged in wood for more structure."),
  v:()=>fSvg(`${fTank(90,40,100,130,{col:"#f3b7a6",lv:.8,cold:1,bub:8})}${fThermo(220,60,"12–18 °C",.3,"#3b7fa8")}${fD(.8,fChip(140,186,w3("acciaio, freddo, niente ossigeno","inox, froid, pas d'oxygène","steel, cool, no oxygen")))}${fD(1.4,fChip(70,28,w3("di solito niente malolattica","en général pas de malolactique","usually no malolactic"),"#8c1d40"))}`)},
 {h:I3("Gli stili di rosato","Les styles de rosé","Rosé styles"),
  c:I3("Gli stili vanno dal secco pallido della Provenza, con Grenache, Cinsault, Syrah, Mourvèdre e Rolle, al Tavel più pieno; dai rosati semisecchi della Loira, come il Rosé d'Anjou da Grolleau, fino al White Zinfandel californiano, dolce e leggero. Quasi tutti si bevono giovani, freschi di frutto.",
   "Les styles vont du sec pâle de Provence, avec grenache, cinsault, syrah, mourvèdre et rolle, au tavel plus ample ; des rosés demi-secs de Loire, comme le rosé d'Anjou de grolleau, jusqu'au white zinfandel californien, doux et léger. Presque tous se boivent jeunes, sur le fruit frais.",
   "Styles range from the pale dry rosés of Provence, made with Grenache, Cinsault, Syrah, Mourvèdre and Rolle, to the fuller Tavel; from off-dry Loire rosés such as Grolleau-based Rosé d'Anjou to California's sweet, light White Zinfandel. Almost all are drunk young, while the fruit is fresh."),
  v:()=>fSvg(xRoseRow(["#f6d7c0","#f3b7a6","#e98e9a","#d9566e"],[I3("Provenza: secco, pallido","Provence : sec, pâle","Provence: dry, pale"),I3("Tavel: pieno","Tavel : ample","Tavel: fuller"),I3("Rosé d'Anjou: semisecco","Rosé d'Anjou : demi-sec","Rosé d'Anjou: off-dry"),I3("White Zinfandel: dolce","White zinfandel : doux","White Zinfandel: sweet")],110),"dusk")},
 {h:I3("Ricapitolando","En résumé","Recap"),
  c:I3("Quattro strade per il rosato: pressatura diretta per i più pallidi; macerazione breve per i più colorati; salasso, che dà anche un rosso più concentrato; taglio di rosso e bianco, vietato in Europa per i rosati fermi ma usato nello Champagne rosé. Poi il mosto si vinifica al fresco, come un bianco.",
   "Quatre chemins vers le rosé : pressurage direct pour les plus pâles ; macération courte pour les plus colorés ; saignée, qui donne aussi un rouge plus concentré ; assemblage de rouge et de blanc, interdit en Europe pour les rosés tranquilles mais utilisé pour le champagne rosé. Ensuite le moût se vinifie au frais, comme un blanc.",
   "Four routes to rosé: direct pressing for the palest; short maceration for deeper colour; saignée, which also gives a more concentrated red; blending red and white, banned in Europe for still rosé but used for rosé Champagne. Then the juice is fermented cool, like a white."),
  v:()=>fSvg(fFlow([{t:I3("uve nere","raisins noirs","black grapes"),io:1},I3("pressatura diretta","pressurage direct","direct pressing"),I3("macerazione breve","macération courte","short maceration"),I3("salasso","saignée","saignée"),I3("fermentazione fresca, senza bucce","fermentation fraîche, sans peaux","cool ferment, off skins"),{t:I3("rosato","rosé","rosé"),io:1}],4,{per:3,stag:1,bh:34,gy:30,y0:30}))}
]},

/* ===================== MALOLACTIC ===================== */
{id:"mlf",sec:"c",ch:"vin",ic:"order",nw:1,t:I3("La fermentazione malolattica","La fermentation malolactique","Malolactic conversion"),s:[
 {h:I3("Che cos'è","Qu'est-ce que c'est","What it is"),
  c:I3("La fermentazione malolattica non riguarda lo zucchero. Sono batteri lattici, soprattutto Oenococcus oeni, che trasformano l'acido malico, aspro come una mela verde, in acido lattico, più morbido, come quello del latte. Si libera anche un po' di anidride carbonica. Di solito avviene dopo la fermentazione alcolica.",
   "La fermentation malolactique ne concerne pas le sucre. Ce sont des bactéries lactiques, surtout Oenococcus oeni, qui transforment l'acide malique, vif comme une pomme verte, en acide lactique, plus doux, comme celui du lait. Elle libère aussi un peu de gaz carbonique. Elle a lieu en général après la fermentation alcoolique.",
   "Malolactic conversion has nothing to do with sugar. Lactic bacteria, mainly Oenococcus oeni, turn malic acid, tart like a green apple, into lactic acid, softer, like the acid in milk. A little carbon dioxide is released too. It usually happens after the alcoholic fermentation."),
  v:()=>fSvg(`${xMol(70,90,w3("acido malico","acide malique","malic acid"),"#5e8c31",w3("mela verde","pomme verte","green apple"))}${fD(.6,xBact(140,80)+xBact(150,100,-6)+xBact(136,116))}${fD(1,fArrow("M100 90H210",null,1))}${fD(1.6,xMol(250,90,w3("acido lattico","acide lactique","lactic acid"),"#c9a46a",w3("latte","lait","milk")))}${fD(2.2,fChip(250,140,"+ CO₂"))}${fChip(145,40,"Oenococcus oeni")}`)},
 {h:I3("Gli effetti sul vino","Les effets sur le vin","Effects on the wine"),
  c:I3("Il vino diventa meno acido e più morbido al palato. I batteri producono anche il diacetile, una sostanza che sa di burro, e note di panna o di frutta secca: sono aromi secondari. Infine il vino diventa più stabile, perché la malolattica non potrà più ripartire in bottiglia.",
   "Le vin devient moins acide et plus souple en bouche. Les bactéries produisent aussi du diacétyle, une substance qui sent le beurre, et des notes de crème ou de fruits secs : ce sont des arômes secondaires. Enfin le vin devient plus stable, car la malolactique ne pourra plus repartir en bouteille.",
   "The wine becomes less acidic and softer on the palate. The bacteria also produce diacetyl, a compound that smells of butter, plus notes of cream or nuts: these are secondary aromas. Finally the wine becomes more stable, as malolactic can no longer start up in the bottle."),
  v:()=>fSvg(`${fD(.1,xBox(30,40,120,30,w3("acidità ↓  morbidezza ↑","acidité ↓  souplesse ↑","acidity ↓  softness ↑")))}${fD(.7,xBox(30,82,120,30,w3("burro · panna (diacetile)","beurre · crème (diacétyle)","butter · cream (diacetyl)"),"rgba(212,162,58,.35)"))}${fD(1.3,xBox(30,124,120,30,w3("stabilità in bottiglia","stabilité en bouteille","stability in bottle")))}${fD(.4,fGlass(230,120,"#e9d27a",1.5))}`)},
 {h:I3("Le condizioni giuste","Les bonnes conditions","The right conditions"),
  c:I3("I batteri lavorano bene se il vino è tiepido, intorno ai venti gradi, e se c'è poca anidride solforosa. Possono essere naturalmente presenti in cantina, oppure il produttore li inocula con batteri selezionati. Per bloccarla invece si raffredda il vino, si aggiunge solforosa e si filtra.",
   "Les bactéries travaillent bien si le vin est tiède, autour de vingt degrés, et s'il y a peu de dioxyde de soufre. Elles peuvent être naturellement présentes au chai, ou le producteur les ensemence avec des bactéries sélectionnées. Pour la bloquer, au contraire, on refroidit le vin, on ajoute du soufre et on filtre.",
   "The bacteria work well if the wine is warm, around twenty degrees, and if there is little sulfur dioxide. They may be present naturally in the winery, or the winemaker inoculates selected bacteria. To block it, the wine is chilled, sulfur dioxide is added and the wine is filtered."),
  v:()=>fSvg(`${fThermo(40,60,"≈ 20 °C",.55)}${fD(.5,xBox(70,50,116,30,w3("poca SO₂","peu de SO₂","little SO₂"),"rgba(94,140,49,.4)"))}${fD(1,xBox(70,90,116,30,w3("batteri naturali o inoculati","bactéries naturelles ou ensemencées","natural or inoculated bacteria"),"rgba(94,140,49,.4)"))}${fD(1.8,xBox(200,40,100,26,w3("BLOCCARE:","BLOQUER :","TO BLOCK:"),"#8c1d40"))}${fD(2.2,xBox(200,72,100,24,w3("freddo","froid","chilling")))}${fD(2.5,xBox(200,100,100,24,"+ SO₂"))}${fD(2.8,xBox(200,128,100,24,w3("filtrazione","filtration","filtration")))}`)},
 {h:I3("Nei rossi: quasi sempre","Dans les rouges : presque toujours","In reds: almost always"),
  c:I3("Quasi tutti i vini rossi fanno la malolattica. Ammorbidisce l'acidità, si integra con il tannino e rende il vino stabile. Spesso si svolge in barrique, dove il contatto con il legno aiuta frutto e rovere a fondersi; nei rossi gli aromi di burro restano in genere poco evidenti.",
   "Presque tous les vins rouges font leur malolactique. Elle assouplit l'acidité, s'intègre au tanin et rend le vin stable. Elle se déroule souvent en barrique, où le contact avec le bois aide le fruit et le chêne à se fondre ; dans les rouges, les arômes de beurre restent en général discrets.",
   "Almost all red wines go through malolactic conversion. It softens acidity, blends with the tannin and makes the wine stable. It often takes place in barrel, where contact with the wood helps fruit and oak to integrate; in reds the buttery aromas usually stay discreet."),
  v:()=>fSvg(`${[70,160,250].map((x,i)=>fD(i*.3,fBarrel(x,110,1,{cut:1,col:"#5a0f24"}))).join("")}${fD(1,xBact(60,112)+xBact(150,110,-6)+xBact(240,112))}${fChip(160,44,w3("rossi: malolattica quasi sempre","rouges : malolactique presque toujours","reds: almost always"))}`)},
 {h:I3("Nei bianchi: una scelta di stile","Dans les blancs : un choix de style","In whites: a style choice"),
  c:I3("Nei bianchi è una decisione del produttore. Per uno Chardonnay pieno e cremoso, in Borgogna o nel Nuovo Mondo, la malolattica aggiunge rotondità e note burrose. Per Riesling e Sauvignon Blanc di solito si blocca, per conservare l'acidità vivace e la purezza del frutto. Si può anche farla solo su una parte del vino.",
   "Dans les blancs, c'est une décision du producteur. Pour un chardonnay ample et crémeux, en Bourgogne ou dans le Nouveau Monde, la malolactique ajoute rondeur et notes beurrées. Pour le riesling et le sauvignon blanc, on la bloque en général, pour garder une acidité vive et la pureté du fruit. On peut aussi la faire sur une partie du vin seulement.",
   "In whites it is the winemaker's call. For a full, creamy Chardonnay, in Burgundy or the New World, malolactic adds roundness and buttery notes. For Riesling and Sauvignon Blanc it is usually blocked, to keep lively acidity and pure fruit. It can also be done on just part of the wine."),
  v:()=>fSvg(`${fD(.1,fGlass(80,110,"#e7c95f",1.4)+fT(80,170,"Chardonnay",9))}${fD(.4,fChip(80,40,w3("sì: burro, rotondità","oui : beurre, rondeur","yes: butter, roundness")))}${fD(.8,fGlass(240,110,"#efe8a8",1.4)+fT(240,170,"Riesling · Sauvignon",9))}${fD(1.2,fChip(240,40,w3("no: acidità e frutto","non : acidité et fruit","no: acidity and fruit"),"#8c1d40"))}${fD(1.8,fChip(160,190,w3("possibile anche parziale","possible en partie","can be partial")))}`)},
 {h:I3("Se parte in bottiglia","Si elle démarre en bouteille","If it starts in bottle"),
  c:I3("Una malolattica che parte dopo l'imbottigliamento è un difetto: il vino diventa leggermente frizzante, torbido e può sviluppare odori sgradevoli. Per questo, prima di imbottigliare, il produttore si assicura che sia completata, oppure la impedisce con solforosa e filtrazione sterile.",
   "Une malolactique qui démarre après la mise en bouteille est un défaut : le vin devient légèrement perlant, trouble et peut développer de mauvaises odeurs. C'est pourquoi, avant la mise, le producteur s'assure qu'elle est terminée, ou l'empêche avec du soufre et une filtration stérile.",
   "Malolactic that starts after bottling is a fault: the wine turns slightly fizzy, cloudy and can develop unpleasant smells. So before bottling the winemaker makes sure it is finished, or prevents it with sulfur dioxide and sterile filtration."),
  v:()=>fSvg(`${fBottle(110,110,{col:"#d9c98a",bub:1})}${fD(.6,fCall(118,100,200,60,w3("frizzante, torbido","perlant, trouble","fizzy, cloudy"),0,"#e2622a"))}${fD(1.2,fFilterSurface(250,150))}${fD(1.6,fChip(250,180,w3("completata o filtrata","terminée ou filtrée","completed or filtered")))}`)},
 {h:I3("Ricapitolando","En résumé","Recap"),
  c:I3("Batteri lattici trasformano l'acido malico in lattico: meno acidità, più morbidezza, aromi di burro e un vino stabile. Ama il calore e poca solforosa; si blocca con freddo, solforosa e filtrazione. Quasi sempre nei rossi; nei bianchi è una scelta: sì per Chardonnay ricchi, no per Riesling e Sauvignon.",
   "Les bactéries lactiques transforment l'acide malique en acide lactique : moins d'acidité, plus de souplesse, des arômes de beurre et un vin stable. Elle aime la chaleur et peu de soufre ; on la bloque par le froid, le soufre et la filtration. Presque toujours dans les rouges ; dans les blancs c'est un choix : oui pour les chardonnays riches, non pour riesling et sauvignon.",
   "Lactic bacteria turn malic into lactic acid: less acidity, more softness, buttery aromas and a stable wine. It likes warmth and little sulfur dioxide; it is blocked by chilling, sulfur dioxide and filtration. Almost always in reds; in whites it is a choice: yes for rich Chardonnay, no for Riesling and Sauvignon."),
  v:()=>fSvg(fFlow([{t:I3("acido malico","acide malique","malic acid"),io:1},"Oenococcus oeni",I3("≈20 °C, poca SO₂","≈20 °C, peu de SO₂","≈20 °C, little SO₂"),{t:I3("acido lattico + burro","acide lactique + beurre","lactic acid + butter"),io:1}],3,{per:4,stag:1,bh:44,y0:70}))}
]},

/* ===================== SWEET WINES ===================== */
{id:"sweet2",sec:"c",ch:"wht",ic:"order",nw:1,t:I3("Vini dolci: tutte le tecniche e i loro vini","Vins doux : toutes les techniques et leurs vins","Sweet wines: every technique and its wines"),s:[
 {h:I3("Tre strade per la dolcezza","Trois chemins vers la douceur","Three roads to sweetness"),
  c:I3("Un vino è dolce quando contiene zucchero non fermentato. Per ottenerlo ci sono tre strade: fermare la fermentazione prima che finisca; aggiungere una componente dolce a un vino secco; oppure concentrare lo zucchero nell'uva, con l'appassimento in pianta o dopo la raccolta, la muffa nobile o il gelo. Per ogni tecnica vediamo i vini da conoscere.",
   "Un vin est doux quand il contient du sucre non fermenté. Pour y arriver, trois chemins : arrêter la fermentation avant la fin ; ajouter un élément doux à un vin sec ; ou concentrer le sucre dans le raisin, par le passerillage sur souche ou après la récolte, la pourriture noble ou le gel. Pour chaque technique, voyons les vins à connaître.",
   "A wine is sweet when it contains unfermented sugar. There are three roads to it: stop the fermentation before it finishes; add a sweet component to a dry wine; or concentrate the sugar in the grape, by drying on the vine or after picking, noble rot or freezing. For each technique, here are the wines to know."),
  v:()=>fSvg(fFlow([I3("fermare la fermentazione","arrêter la fermentation","stop fermentation"),I3("aggiungere dolcezza","ajouter de la douceur","add sweetness"),I3("concentrare lo zucchero","concentrer le sucre","concentrate sugar")],-1,{per:3,stag:1,bh:46,y0:60}))},
 {h:I3("Fermare con l'alcol: i vini fortificati","Arrêter avec de l'alcool : les vins mutés","Stopping with spirit: fortified wines"),
  c:I3("Aggiungendo alcol d'uva durante la fermentazione, il grado sale a circa quindici per cento o più e i lieviti muoiono: lo zucchero rimasto resta nel vino. Esempi: i vini dolci naturali francesi, come il Muscat de Beaumes-de-Venise e il Muscat de Rivesaltes, il Banyuls e il Maury da Grenache; il Porto; i Moscati fortificati di Rutherglen, in Australia.",
   "En ajoutant de l'alcool de raisin pendant la fermentation, le degré monte à environ quinze pour cent ou plus et les levures meurent : le sucre restant reste dans le vin. Exemples : les vins doux naturels français, comme le muscat de Beaumes-de-Venise et le muscat de Rivesaltes, le banyuls et le maury de grenache ; le porto ; les muscats mutés de Rutherglen, en Australie.",
   "Adding grape spirit during fermentation raises the alcohol to about fifteen percent or more and kills the yeast: the remaining sugar stays in the wine. Examples: French vins doux naturels such as Muscat de Beaumes-de-Venise and Muscat de Rivesaltes, Grenache-based Banyuls and Maury; Port; the fortified Muscats of Rutherglen, in Australia."),
  v:()=>fSvg(`${fTank(40,50,90,110,{col:"#e7c95f",lv:.75,bub:8})}${fD(.6,xStill(170,140))}${fD(.9,`<path d="M150 104C140 84 136 76 130 74" stroke="#f3e8c8" stroke-width="4" marker-end="url(#fah)" fill="none"/>`)}${fD(1.2,fChip(85,36,w3("lieviti fermati ≈15 %+","levures arrêtées ≈15 %+","yeast stopped ≈15%+"),"#8c1d40"))}${fD(1.6,xBox(206,40,108,24,"Muscat de Beaumes-de-Venise"))}${fD(1.9,xBox(206,70,108,24,"Banyuls · Maury"))}${fD(2.2,xBox(206,100,108,24,w3("Porto","Porto","Port")))}${fD(2.5,xBox(206,130,108,24,"Rutherglen Muscat"))}`)},
 {h:I3("Fermare con il freddo e la filtrazione","Arrêter par le froid et la filtration","Stopping with chilling and filtration"),
  c:I3("Senza aggiungere alcol, si raffredda la vasca, si aggiunge solforosa e si tolgono i lieviti con la filtrazione. Il vino resta dolce, fruttato e poco alcolico. Esempi: il Moscato d'Asti e l'Asti in Piemonte; molti Riesling tedeschi dolci e leggeri, come i Kabinett e gli Spätlese della Mosella. A volte, con zucchero molto concentrato, i lieviti si fermano da soli.",
   "Sans ajouter d'alcool, on refroidit la cuve, on ajoute du soufre et on retire les levures par filtration. Le vin reste doux, fruité et peu alcoolisé. Exemples : le moscato d'Asti et l'asti dans le Piémont ; de nombreux rieslings allemands doux et légers, comme les kabinett et spätlese de Moselle. Parfois, avec un sucre très concentré, les levures s'arrêtent d'elles-mêmes.",
   "Without adding spirit, the vat is chilled, sulfur dioxide added and the yeast filtered out. The wine stays sweet, fruity and low in alcohol. Examples: Moscato d'Asti and Asti in Piedmont; many light, sweet German Rieslings, such as Mosel Kabinett and Spätlese. Sometimes, with very concentrated sugar, the yeast stops by itself."),
  v:()=>fSvg(`${fTank(40,40,90,130,{col:"#efe3a0",lv:.8,cold:1})}${fThermo(146,60,"0–4 °C",.1,"#3b7fa8")}${fD(.6,fChip(200,40,"+ SO₂ · "+w3("filtrazione","filtration","filtration")))}${fD(1,xBox(186,70,128,26,"Moscato d'Asti 4,5–6,5 %"))}${fD(1.4,xBox(186,102,128,26,w3("Riesling Kabinett della Mosella","riesling kabinett de Moselle","Mosel Riesling Kabinett")))}${fD(1.8,xBox(186,134,128,26,w3("Spätlese dolce","spätlese doux","sweet Spätlese")))}`)},
 {h:I3("Aggiungere dolcezza: la riserva dolce","Ajouter de la douceur : la réserve douce","Adding sweetness: sweet reserve"),
  c:I3("Si fermenta il vino fino al secco e poi si aggiunge mosto d'uva non fermentato, la riserva dolce, Süssreserve in Germania. È un modo preciso di regolare la dolcezza, usato soprattutto per vini semplici ed economici, per esempio molti vini tedeschi di base e alcuni vini del Nuovo Mondo leggermente abboccati. Bisogna evitare che rifermentino in bottiglia.",
   "On fermente le vin jusqu'au sec puis on ajoute du moût de raisin non fermenté, la réserve douce, Süssreserve en Allemagne. C'est un moyen précis de régler la douceur, utilisé surtout pour des vins simples et bon marché, par exemple beaucoup de vins allemands d'entrée de gamme et certains vins du Nouveau Monde légèrement doux. Il faut éviter qu'ils refermentent en bouteille.",
   "The wine is fermented to dryness and then unfermented grape juice is added: sweet reserve, Süssreserve in Germany. It is a precise way to set sweetness, used mainly for simple, inexpensive wines, for example many entry-level German wines and some off-dry New World wines. They must not referment in the bottle."),
  v:()=>fSvg(`${fTank(50,60,90,110,{col:"#efe8b0",lv:.8})}${fT(95,184,w3("vino secco","vin sec","dry wine"),8.5)}${fD(.6,fTank(190,80,70,90,{col:"#e9c75a",lv:.7}))}${fT(225,184,"Süssreserve",8.5)}${fD(1.2,`<path d="M190 110C172 100 162 100 144 104" stroke="#e9c75a" stroke-width="4" marker-end="url(#fah)" fill="none"/>`)}${fD(1.6,fChip(160,36,w3("vini tedeschi di base · vini abboccati","vins allemands d'entrée de gamme · vins demi-secs","entry-level German · off-dry wines")))}`)},
 {h:I3("Appassimento in pianta: passerillage e vendemmia tardiva","Passerillage sur souche et vendanges tardives","Drying on the vine: late harvest"),
  c:I3("L'uva sana viene lasciata sulla pianta ben oltre la normale vendemmia. Perde acqua, gli acini avvizziscono e zucchero e aromi si concentrano: è il passerillage. Serve un autunno secco e soleggiato. Esempi: il Jurançon moelleux da Petit e Gros Manseng, nel Sud-Ovest della Francia; i Vendanges Tardives d'Alsazia; alcuni Coteaux du Layon e Vouvray moelleux nella Loira; gli Spätlese e Auslese tedeschi; i Late Harvest del Nuovo Mondo, in California, Cile e Sudafrica.",
   "Le raisin sain reste sur la vigne bien au-delà de la vendange normale. Il perd de l'eau, les baies se flétrissent, sucre et arômes se concentrent : c'est le passerillage. Il faut un automne sec et ensoleillé. Exemples : le jurançon moelleux de petit et gros manseng, dans le Sud-Ouest ; les vendanges tardives d'Alsace ; certains coteaux-du-layon et vouvray moelleux en Loire ; les spätlese et auslese allemands ; les late harvest du Nouveau Monde, en Californie, au Chili et en Afrique du Sud.",
   "Healthy grapes are left on the vine well past the normal harvest. They lose water, the berries shrivel and sugar and flavour concentrate: this is passerillage. A dry, sunny autumn is needed. Examples: sweet Jurançon from Petit and Gros Manseng in south-west France; Alsace Vendanges Tardives; some Coteaux du Layon and sweet Vouvray in the Loire; German Spätlese and Auslese; New World Late Harvest wines from California, Chile and South Africa."),
  v:()=>fSvg(`${fVine("autumn")}${[0,1,2,3].map(i=>fD(.6+i*.25,xBotry(118+i*22,132,5).replace(/#cfc6b8/g,"#7a4a2a"))).join("")}${fD(.4,fChip(160,30,w3("autunno secco: l'acino avvizzisce","automne sec : la baie se flétrit","dry autumn: the berry shrivels")))}${fD(1.4,xBoxD(6,150,96,22,"Jurançon moelleux"))}${fD(1.7,xBoxD(108,150,104,22,w3("Alsazia: Vendanges Tardives","Alsace : vendanges tardives","Alsace Vendanges Tardives")))}${fD(2,xBoxD(218,150,96,22,"Coteaux du Layon"))}${fD(2.3,xBoxD(56,176,100,20,"Spätlese · Auslese"))}${fD(2.6,xBoxD(164,176,100,20,"Late Harvest (USA, Cile)"))}`,"autumn")},
 {h:I3("La muffa nobile","La pourriture noble","Noble rot"),
  c:I3("Con mattine nebbiose e pomeriggi caldi e secchi, il fungo Botrytis cinerea fora la buccia degli acini maturi: l'acqua evapora, zuccheri e acidi si concentrano e nascono aromi di miele, albicocca, marmellata. Si raccoglie a più passaggi. Esempi: Sauternes e Barsac, Monbazillac; Quarts de Chaume e Bonnezeaux nella Loira; le Sélection de Grains Nobles d'Alsazia; Beerenauslese e Trockenbeerenauslese tedeschi e austriaci; il Tokaji Aszú.",
   "Avec des matins brumeux et des après-midi chauds et secs, le champignon Botrytis cinerea perce la peau des baies mûres : l'eau s'évapore, sucres et acides se concentrent, et apparaissent des arômes de miel, d'abricot, de marmelade. On vendange en plusieurs tries. Exemples : sauternes et barsac, monbazillac ; quarts-de-chaume et bonnezeaux en Loire ; les sélections de grains nobles d'Alsace ; beerenauslese et trockenbeerenauslese allemands et autrichiens ; le tokaji aszú.",
   "With misty mornings and warm, dry afternoons, the fungus Botrytis cinerea pierces the skins of ripe berries: water evaporates, sugars and acids concentrate, and aromas of honey, apricot and marmalade appear. Picking is done in several passes. Examples: Sauternes and Barsac, Monbazillac; Quarts de Chaume and Bonnezeaux in the Loire; Alsace Sélection de Grains Nobles; German and Austrian Beerenauslese and Trockenbeerenauslese; Tokaji Aszú."),
  v:()=>fSvg(`${fFog(20,110,280)}${xBotry(70,80,20)}${xBotry(108,74,17)}${xBotry(90,108,19)}${fD(.6,fChip(90,30,w3("botrite: acqua che evapora","botrytis : l'eau s'évapore","botrytis: water evaporates")))}${fD(1,xBoxD(170,40,144,22,"Sauternes · Barsac · Monbazillac"))}${fD(1.3,xBoxD(170,68,144,22,"Quarts de Chaume · Bonnezeaux"))}${fD(1.6,xBoxD(170,96,144,22,w3("Alsazia: SGN","Alsace : SGN","Alsace SGN")))}${fD(1.9,xBoxD(170,124,144,22,"BA · TBA"))}${fD(2.2,xBoxD(170,152,144,22,"Tokaji Aszú"))}`,"autumn")},
 {h:I3("Appassimento dopo la raccolta","Passerillage après la récolte","Drying after picking"),
  c:I3("L'uva viene raccolta e messa ad appassire per settimane o mesi: su graticci o appesa in locali ventilati, oppure al sole su stuoie. Esempi: Recioto della Valpolicella e Recioto di Soave; il Vin Santo toscano; il Passito di Pantelleria da Zibibbo; il Vinsanto di Santorini da Assyrtiko; il Vin de Paille del Giura; e lo Sherry Pedro Ximénez, con uve seccate al sole.",
   "Le raisin est récolté puis mis à sécher pendant des semaines ou des mois : sur des claies ou suspendu dans des locaux ventilés, ou bien au soleil sur des nattes. Exemples : recioto della valpolicella et recioto di soave ; le vin santo toscan ; le passito di Pantelleria de zibibbo ; le vinsanto de Santorin d'assyrtiko ; le vin de paille du Jura ; et le xérès pedro ximénez, aux raisins séchés au soleil.",
   "The grapes are picked and then dried for weeks or months: on racks or hung in airy lofts, or in the sun on mats. Examples: Recioto della Valpolicella and Recioto di Soave; Tuscan Vin Santo; Passito di Pantelleria from Zibibbo; Santorini Vinsanto from Assyrtiko; Jura Vin de Paille; and Pedro Ximénez Sherry, from sun-dried grapes."),
  v:()=>fSvg(`${xRack(10,70,120,1)}${fD(.5,fSun(150,30,10))}${fD(.7,xMats(10,172,2).replace('translate(10 172)','translate(10 172) scale(.95)'))}${fD(1,xBox(150,50,164,22,"Recioto della Valpolicella · di Soave"))}${fD(1.3,xBox(150,78,164,22,"Vin Santo"))}${fD(1.6,xBox(150,106,164,22,"Passito di Pantelleria"))}${fD(1.9,xBox(150,134,164,22,w3("Vinsanto di Santorini","Vinsanto de Santorin","Santorini Vinsanto")))}${fD(2.2,xBox(150,162,164,22,"Vin de Paille · Pedro Ximénez"))}`)},
 {h:I3("Il gelo: Eiswein e Icewine","Le gel : Eiswein et icewine","Freezing: Eiswein and Icewine"),
  c:I3("L'uva sana resta sulla pianta fino all'inverno e si raccoglie gelata, di notte, ad almeno meno sette gradi in Germania e meno otto in Canada. Pressando gli acini congelati il ghiaccio resta nella pressa e scorre solo un succo dolcissimo e molto acido. Esempi: l'Eiswein tedesco e austriaco, soprattutto da Riesling; l'Icewine canadese dell'Ontario, da Riesling e dall'ibrido Vidal.",
   "Le raisin sain reste sur la vigne jusqu'à l'hiver et se vendange gelé, la nuit, à moins sept degrés au moins en Allemagne et moins huit au Canada. En pressant les baies congelées, la glace reste dans le pressoir et seul s'écoule un jus très doux et très acide. Exemples : l'Eiswein allemand et autrichien, surtout de riesling ; l'icewine canadien de l'Ontario, de riesling et de l'hybride vidal.",
   "Healthy grapes stay on the vine into winter and are picked frozen, at night, at minus seven degrees or colder in Germany and minus eight in Canada. When the frozen berries are pressed, the ice stays in the press and only a very sweet, very acidic juice flows. Examples: German and Austrian Eiswein, mostly from Riesling; Canadian Icewine from Ontario, from Riesling and the hybrid Vidal."),
  v:()=>fSvg(`${fMoon(270,30)}${fSnow()}${fVine("ripe")}${fD(.6,fThermo(30,60,"−7 / −8 °C",.05,"#3b7fa8"))}${fD(1.2,fChip(160,36,w3("Eiswein (Germania, Austria) · Icewine (Ontario)","Eiswein (Allemagne, Autriche) · icewine (Ontario)","Eiswein (Germany, Austria) · Icewine (Ontario)")))}${fD(1.8,fCrystals(140,150,"#e6f4fb"))}${fD(2.2,fChip(160,190,"Riesling · Vidal"))}`,"night")},
 {h:I3("Ricapitolando","En résumé","Recap"),
  c:I3("Fermare con l'alcol: vini dolci naturali, Porto, Rutherglen. Fermare con freddo e filtrazione: Moscato d'Asti, Riesling tedeschi leggeri. Riserva dolce: vini tedeschi semplici. Appassimento in pianta: Jurançon, Vendanges Tardives, Late Harvest. Muffa nobile: Sauternes, SGN, BA, TBA, Tokaji. Appassimento dopo la raccolta: Recioto, Vin Santo, Pantelleria, Pedro Ximénez. Gelo: Eiswein e Icewine.",
   "Arrêter avec l'alcool : vins doux naturels, porto, Rutherglen. Arrêter par le froid et la filtration : moscato d'Asti, rieslings allemands légers. Réserve douce : vins allemands simples. Passerillage sur souche : jurançon, vendanges tardives, late harvest. Pourriture noble : sauternes, SGN, BA, TBA, tokaji. Passerillage après récolte : recioto, vin santo, Pantelleria, pedro ximénez. Gel : Eiswein et icewine.",
   "Stopping with spirit: vins doux naturels, Port, Rutherglen. Stopping with chilling and filtration: Moscato d'Asti, light German Rieslings. Sweet reserve: simple German wines. Drying on the vine: Jurançon, Vendanges Tardives, Late Harvest. Noble rot: Sauternes, SGN, BA, TBA, Tokaji. Drying after picking: Recioto, Vin Santo, Pantelleria, Pedro Ximénez. Freezing: Eiswein and Icewine."),
  v:()=>fSvg(fTable(null,[
    [I3("Alcol (mutizzazione)","Alcool (mutage)","Spirit (fortification)"),I3("VDN, Porto, Rutherglen","VDN, porto, Rutherglen","VDN, Port, Rutherglen")],
    [I3("Freddo + SO₂ + filtro","Froid + SO₂ + filtre","Chill + SO₂ + filter"),I3("Moscato d'Asti, Kabinett","Moscato d'Asti, kabinett","Moscato d'Asti, Kabinett")],
    [I3("Riserva dolce","Réserve douce","Sweet reserve"),I3("vini tedeschi semplici","vins allemands simples","simple German wines")],
    [I3("Passerillage in pianta","Passerillage sur souche","Drying on the vine"),I3("Jurançon, VT, Late Harvest","Jurançon, VT, late harvest","Jurançon, VT, Late Harvest")],
    [I3("Muffa nobile","Pourriture noble","Noble rot"),I3("Sauternes, SGN, TBA, Tokaji","Sauternes, SGN, TBA, tokaji","Sauternes, SGN, TBA, Tokaji")],
    [I3("Appassimento","Passerillage après récolte","Drying after picking"),I3("Recioto, Vin Santo, PX","Recioto, vin santo, PX","Recioto, Vin Santo, PX")],
    [I3("Gelo","Gel","Freezing"),I3("Eiswein, Icewine","Eiswein, icewine","Eiswein, Icewine")]],[3],{c1:130}))}
]}
);
